# ARIMA small grid, based on AIC
arima_results=[]
with warnings.catch_warnings():
    warnings.simplefilter("ignore")
    for order in [(p,d,q) for p in range(3) for d in [0,1] for q in range(3)]:
        for seas in [(P,D,Q,12) for P in range(2) for D in [0,1] for Q in range(2)]:
            try:
                mod=SARIMAX(y, order=order, seasonal_order=seas, enforce_stationarity=False, enforce_invertibility=False)
                res=mod.fit(disp=False, maxiter=200)
                f=res.get_forecast(3).predicted_mean.iloc[-1]
                arima_results.append((res.aic,order,seas,f,res))
            except Exception as e:
                pass
arima_results_sorted=sorted(arima_results, key=lambda x:x[0])
len(arima_results_sorted), arima_results_sorted[:10]

def forecast_model(train,h,name):
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        if name=='ets_add':
            return ExponentialSmoothing(train, seasonal='add', seasonal_periods=12, initialization_method='estimated').fit(optimized=True, use_brute=True).forecast(h)
        if name=='ets_trend_add':
            return ExponentialSmoothing(train, trend='add', seasonal='add', seasonal_periods=12, initialization_method='estimated').fit(optimized=True, use_brute=True).forecast(h)
        if name=='ses':
            return SimpleExpSmoothing(train, initialization_method='estimated').fit().forecast(h)
        if name=='holt':
            return Holt(train, initialization_method='estimated').fit().forecast(h)
        if name=='ridge':
            return reg_forecast(train,h,'ridge')
        if name=='linear':
            return reg_forecast(train,h,'linear')
        if name=='rf':
            return reg_forecast(train,h,'rf')
        if name=='snaive':
            fut_idx=pd.date_range(train.index[-1]+pd.offsets.MonthBegin(1), periods=h, freq='MS')
            vals=[]
            for dt in fut_idx:
                prev=dt-pd.DateOffset(years=1)
                vals.append(train.loc[prev] if prev in train.index else train.iloc[-1])
            return pd.Series(vals,index=fut_idx)
        if name.startswith('sarima'):
            # parse configs
            cfg=name.split(':')[1]
            order, seas=eval(cfg)
            res=SARIMAX(train, order=order, seasonal_order=seas, enforce_stationarity=False, enforce_invertibility=False).fit(disp=False, maxiter=100)
            return res.get_forecast(h).predicted_mean

# choose a few SARIMA configs
sarima_names=[]
for aic,order,seas,f,res in arima_results_sorted[:10]:
    sarima_names.append(f"sarima:{(order,seas)}")
models=['ets_add','ets_trend_add','ses','holt','ridge','linear','rf','snaive']+sarima_names[:6]
errors={m:[] for m in models}
preds_records=[]
h=3
# rolling origins with min 24 months, at least target available
for end_pos in range(18, len(y)-h+1): # train first end_pos observations
    train=y.iloc[:end_pos]
    target=y.iloc[end_pos+h-1]
    target_date=y.index[end_pos+h-1]
    for m in models:
        try:
            pred=forecast_model(train,h,m).iloc[-1]
            if np.isfinite(pred):
                errors[m].append(pred-target)
                preds_records.append((m,train.index[-1],target_date,pred,target,pred-target))
        except Exception as e:
            pass
summary=[]
for m,errs in errors.items():
    if len(errs):
        err=np.array(errs)
        summary.append((m,len(err),np.mean(np.abs(err)),np.sqrt(np.mean(err**2)),np.mean(err),np.median(np.abs(err))))
pd.DataFrame(summary, columns=['model','n','MAE','RMSE','bias','MedAE']).sort_values('MAE').head(20)
